def summarize_ranges(nums: list[int]) -> str:
    nums = sorted(set(nums))
    result = []
    i = 0
    while i < len(nums):
        j = i + 1
        while j < len(nums) and nums[j] == nums[j - 1] + 1:
            j += 1
        if j - i >= 3:
            result.append(f"{nums[i]}..{nums[j - 1]}")
        elif j - i == 2:
            result.append(f"{nums[i]},{nums[j - 1]}")
        else:
            result.append(str(nums[i]))
        i = j
    return ",".join(result)
